from pathlib import Path
import json,csv,re

OUT=Path(__file__).resolve().parent
talks=[]; items=[]; problems=[]; corrections=[]
TODAY="As of 10 November 2026, "

def save():
    for name, data in (("talks",talks),("items",items),("problems",problems)):
        (OUT/(name+".json")).write_text(json.dumps(data,ensure_ascii=False,indent=2)+"\n")
    with (OUT/"corrections.csv").open("w",newline="") as f:
        w=csv.DictWriter(f,fieldnames=["page","place","transcription_reads","should_read","evidence","applies_to","type"])
        w.writeheader();w.writerows(corrections)

def talk(record,date,speaker,pages,title,summary):
    talks.append(dict(record=record,date=date,speaker=speaker,pages=pages,title=title,kind="talk",summary=summary));save()

def item(record,pages,kind,title,notes,statement,fate,refs=(),reconstruction="",cls="E",literal="correct with missing hypotheses",match="exact",verification="read the result",status="",development="annotated",problem="",worth="",confidence="high",speaker=None):
    n=1+sum(x["record"]==record for x in items)
    d=dict(id=f"1979-{record}.{n}",record=record,pages=pages,kind=kind,title=title,notes=notes,statement=statement,reconstruction=reconstruction,**{"class":cls},fate=fate,present_status=TODAY+status,literal_correctness=literal,publication_match=match,verification=verification,development=development,problem=problem,worth=worth,refs=list(refs),confidence=confidence)
    if speaker:d["speaker"]=speaker
    items.append(d);save();return d["id"]

def correction(page,place,reads,should,evidence,applies="both",typ="faithful_error"):
    corrections.append(dict(page=page,place=place,transcription_reads=reads,should_read=should,evidence=evidence,applies_to=applies,type=typ));save()

talk(471,"1979-10-22","I. A. Batalin","P000866","First-class constraints and structure functions",
     r"The dated block on P000866 introduces first-class constraints, asks whether their structure functions can be made constant, and writes a multiplier action. The catalogue attributes it to Batalin; the notebook's tentative \ru{Некто (Батурин)} is retained as an attribution uncertainty. The catalogue's overlapping P000864--P000867 interval is not a literal boundary: the new block starts on P000866 and ends before Kallosh's heading on that page.")
item(471,"P000866","definition","First-class constraints on a symplectic phase space",
     r"The notes set \(g=(q,p)\), use the canonical antisymmetric matrix, and write \(\{T_\alpha,T_\beta\}=u_{\alpha\beta}^{\gamma}T\).",
     r"On a symplectic manifold \((M,\omega)\), let \(C=\{T_1=\cdots=T_m=0\}\) with independent differentials on \(C\). The constraints are first class when \(\{T_\alpha,T_\beta\}|_C=0\); locally regularity gives \(\{T_\alpha,T_\beta\}=u_{\alpha\beta}^{\gamma}T_\gamma\). Equivalently \(C\) is coisotropic. The coefficients depend on the chosen generators and need not be constants.",
     r"This is Dirac's pre-existing distinction: \citet[\S6, pp.~136--138]{dirac1950generalized}; the article derives from lectures given in August 1949 and was published in 1950.",
     ["dirac1950generalized"],reconstruction=r"Regularity and the subscript on the final \(T_\gamma\) are supplied; the geometric formulation is an editorial translation.",status=r"this is the standard local definition; singular constraint sets require separate treatment.")
abel=item(471,"P000866","question","Can structure functions be made constant?",
     r"The explicit question is \ru{можно ли сделать заменами пер., чтобы было \(u_{\alpha\beta}^{\gamma}=\mathrm{const}\)}. It does not specify locality or whether the defining constraint functions may be replaced.",
     r"Locally near a regular point of a coisotropic submanifold of codimension \(m\), one can choose canonical coordinates and equivalent defining functions \(P_1,\ldots,P_m\) so that \(C=\{P_1=\cdots=P_m=0\}\) and \(\{P_a,P_b\}=0\). This affirmative statement allows a nonsingular change of constraint generators. A coordinate change alone, keeping a specified nonconstant coefficient function as the same scalar function, cannot make that function constant.",
     r"Equivalent constraints already occur in \citet[\S8, eq.~(39)]{dirac1950generalized}. \citet[\S1, eqs.~(1.8)--(1.10), and \S2.A]{gogilidze1996abelianization} explicitly study constructive abelianization (preprint 28 April 1995; journal 1996). That later paper does not establish priority for the elementary local normal-form assertion.",
     ["dirac1950generalized","gogilidze1996abelianization"],reconstruction=r"The stated local regular question is a bounded reconstruction. No global abelianization, preservation of covariance, or uniqueness of structure functions is asserted. The notebook's unqualified wording has no single yes/no answer.",match="partial",verification="read the result",status=r"the regular local version with equivalent generators is settled; global, singular, and covariance-preserving versions are different questions and are not attributed to the speaker.",problem="GP-1979-20",confidence="medium")
problems.append(dict(id="GP-1979-20",title="Local abelianization of regular first-class constraints",statement=r"Given independent first-class constraints defining a regular coisotropic submanifold, can local canonical coordinates and an invertible change of constraint generators make all constraint brackets zero? This specifies the local reading of the notebook's question about constant structure functions.",occurrences=[abel],status=r"As of November 2026 the stated local regular version is affirmative. The notebook does not specify the allowed transformations or any global quantifier; it must not be converted into a universal global abelianization conjecture. Dirac's generator equivalence is older; the constructive 1995 preprint/1996 article is a later explicit treatment.",status_date="2026-11",refs=["dirac1950generalized","gogilidze1996abelianization"]));save()
item(471,"P000866","construction","Multiplier action and Hamiltonian gauge directions",
     r"The action is \(S=\int[\frac12 g^a\epsilon_{ab}\dot g^b-H(g)-\lambda^\alpha T_\alpha(g)]\,dt\), followed by the statement that gauge transformations are generated only by first-class constraints.",
     r"For a regular first-class system with \(\{H,T_\alpha\}=V_\alpha{}^\beta T_\beta\), the characteristic directions of \(C\) are generated by the Hamiltonian fields \(X_{T_\alpha}|_C\). The action is invariant up to endpoint terms under the corresponding time-dependent gauge variations when the multipliers transform with the requisite time derivative and structure-function terms and the gauge parameter satisfies the chosen endpoint conditions.",
     r"\citet[\S\S6--8]{dirac1950generalized} gives the constraint and multiplier framework before 1979. The stronger assertion that each arbitrary first-class combination by itself gives a full off-shell Lagrangian gauge transformation needs qualifications.",
     ["dirac1950generalized"],reconstruction=r"Preservation by \(H\), transformations of \(\lambda\), and endpoint conditions are supplied. The canonical one-form in the displayed symmetrized action differs from \(p\,dq\) by an exact term, depending on the matrix convention.",match="partial",status=r"the regular characteristic-distribution statement is established; the displayed action alone does not prove an unrestricted Dirac conjecture.")
correction("P000866","speaker heading","Somebody (Baturin) / Некто (Батурин)","Catalogue attribution: I. A. Batalin; retain the notebook's tentative name as provenance.","Scan P000866 visibly has the tentative parenthesis; upload/GY1979_talks.md assigns record471 to Batalin.",typ="provenance")
correction("P000866","constraint closure formula",r"\{T_\alpha,T_\beta\}=u_{\alpha\beta}^{\gamma}T",r"\{T_\alpha,T_\beta\}=u_{\alpha\beta}^{\gamma}T_\gamma","Scan P000866 has the missing final subscript; the correction is mathematical, not a transcription repair.")

talk(472,"1979-10-22","Renata Kallosh","P000866-P000870","Background-field quantization, ghosts and gauge dependence",
     r"Kallosh relates formal generating functionals and scattering amplitudes, then presents background-field gauge fixing for gravity, ghost terms, and an on-shell gauge-independence argument. Maxwell theory supplies a transparent example of gauge degeneracy. Several formulas suppress normalization, loop order, or curvature terms. The supergravity discussion concerns gauge-algebra and ghost modifications; it does not claim ultraviolet finiteness.")
item(472,"P000866-P000867","construction","Functional integral and perturbative scattering functional",
     r"\(e^{iW[\varphi]}=\int d\phi\,e^{iS[\phi,\varphi]}\) is related to an \(S\)-matrix functional after replacing \(\varphi\) by a solution expressed through an incoming free field.",
     r"After specifying a free propagator, asymptotic conditions, normalization and a perturbative prescription, a generating functional determines time-ordered Green functions, and amputated on-shell limits determine scattering amplitudes when the LSZ hypotheses hold. A bare oscillatory functional integral without a measure is only a formal notation.",
     r"\citet[\S1, pp.~778--779]{faddeevpopov1974gravity} reviews the earlier functional-integral and diagrammatic construction. The Russian review appeared in November 1973, the English translation in 1974.",
     ["faddeevpopov1974gravity"],reconstruction=r"The source's \(W\) is not silently identified with a Legendre-transformed effective action: the distinction between connected generating functional and effective action matters later.",match="partial",status=r"the perturbative construction is standard; these notes do not construct a nonperturbative gravitational measure.")
item(472,"P000867","method","Iterating the classical field equation as a tree expansion",
     r"The field satisfies a schematic equation \(\widetilde\varphi=\varphi_{\rm in}+D^c*(\delta L_{\rm int}/\delta\widetilde\varphi)\), illustrated by tree diagrams.",
     r"For a polynomial interaction and a fixed Green operator \(D\), the equation \(\phi=\phi_0+D N(\phi)\) can be solved recursively as a formal power series in a coupling. Each recursion inserts a vertex and propagator, giving rooted trees. Signs depend on the definition of the free operator; convergence and an incoming scattering interpretation require additional analytic and boundary assumptions.",
     r"\citet[\S1]{faddeevpopov1974gravity} supplies the pre-1979 diagrammatic setting. The precise rooted-tree recursion here is an elementary reconstruction, not an identified new theorem of this talk.",
     ["faddeevpopov1974gravity"],reconstruction=r"The tree recursion is separated from loop corrections and from rigorous existence of a nonlinear wave solution. The notebook's \(D^c\) designation by itself does not fix retarded versus Feynman boundary conditions.",match="partial",status=r"the formal iterative identity is settled; no convergence assertion is present.")
item(472,"P000867-P000868","construction","Background split and harmonic gauge for the metric fluctuation",
     r"The gravitational integral uses \(S[g+h]\), with \(F_\nu=D^\mu[g]h_{\mu\nu}-\frac12D_\nu[g]h^\mu{}_\mu\) and a quadratic gauge-fixing action.",
     r"Fix a smooth nondegenerate background metric \(g\). In a local perturbative gauge, add \(\frac1{2\alpha}\int \sqrt{|g|}\,F_\nu F^\nu\) to the Einstein--Hilbert quadratic fluctuation operator, and include the determinant of the linearized variation of \(F\) along diffeomorphisms. Invertibility means invertibility with specified boundary conditions and after handling residual zero modes.",
     r"Covariant gravitational gauge fixing and its ghost determinant predate the talk: \citet[\S\S2--3]{faddeevpopov1974gravity}.",
     ["faddeevpopov1974gravity"],reconstruction=r"The gauge parameter, boundary conditions and qualification concerning zero modes are explicit additions.",status=r"this remains the conventional perturbative background gauge, with global gauge-copy and measure issues outside the claim.")
item(472,"P000867","claim","The gravitational ghost operator and perturbative unitarity",
     r"The notes write a ghost term schematically as \(\bar c^\nu D_\mu[g]D^\mu[g+h]c_\nu\), and attribute loss of unitarity without an added term to Feynman.",
     r"The Faddeev--Popov operator is \(M_\nu{}^\rho=\delta F_\nu/\delta\xi_\rho\). At \(h=0\), with \(\delta h_{\mu\nu}=\nabla_\mu\xi_\nu+\nabla_\nu\xi_\mu\), it is \(\nabla^2\delta_\nu{}^\rho+R_\nu{}^\rho\), up to curvature and action-sign conventions. Its Grassmann determinant implements cancellations needed for physical perturbative unitarity; gauge fixing alone is not that determinant.",
     r"\citet[introduction and \S3, eqs.~(3.20)--(3.21)]{faddeevpopov1974gravity} distinguishes Feynman's 1963 one-loop observation from later all-order ghost rules. This supplies an exact match for the mechanism, not for the abbreviated operator.",
     ["faddeevpopov1974gravity"],reconstruction=r"The Ricci term and the identification of the indispensable extra term as the ghost determinant are supplied. A positive physical Hilbert-space statement cannot be inferred just from the unconstrained integral.",literal="false as written",match="partial",status=r"the curvature-complete operator and perturbative physical-state cancellation are standard.")
item(472,"P000867","remark","Additional ghost interactions in supergravity",
     r"The text says that one further term suffices in supergravity whereas an arbitrary theory requires infinitely many corrections.",
     r"For a gauge algebra that closes only modulo field equations, the naive determinant-only Faddeev--Popov rules need additional terms. Particular supergravity formulations admit quartic ghost interactions. No precise model, auxiliary-field content or bound on ghost degree is recorded, so the universal one-term/infinitely-many contrast is not a determinate theorem.",
     r"\citet[pp.~141--152]{kallosh1978modified} is the contemporaneous 1978 publication lead; its publisher abstract and metadata were found but the full article was inaccessible. \citet[\S2.2 and introduction]{fuster2005brst} later distinguishes open algebras and the antifield formalism. It does not turn this 1979 remark into a statement of the later BV master-equation theory.",
     ["kallosh1978modified","fuster2005brst"],cls="F",literal="not determinable",match="partial",verification="indirect",status=r"the general open-algebra framework is established, but the notebook's asserted truncation cannot be verified without a specified supergravity model.",confidence="medium")
item(472,"P000868","claim","Diffeomorphism invariance and background covariance",
     r"Equations (9)--(12) compare \(S[g+\delta g]\), \(W[g+\delta g]\), and the induced change of the fluctuation \(h\).",
     r"Einstein--Hilbert action is invariant under diffeomorphisms compatible with boundary data. Simultaneous background and fluctuation transformations can preserve a background-covariant gauge-fixed formal integral if the measure, determinant and regularization preserve that symmetry. Infinitesimal equality is understood to first order in the parameter.",
     r"\citet[\S\S2--3]{faddeevpopov1974gravity} provides the pre-existing covariant construction. Modern BRST qualifications concerning the measure and anomalies are explicit in \citet[\S\S7--9]{fuster2005brst}.",
     ["faddeevpopov1974gravity","fuster2005brst"],reconstruction=r"Background covariance is kept distinct from independence of the choice of gauge-fixing function.",match="partial",status=r"the classical identity is exact under its boundary hypotheses; a quantum version requires anomaly-free symmetry preservation.")
item(472,"P000868-P000869","claim","On-shell gauge independence and its loop-order restriction",
     r"After subtracting \(S[g]\) and its linear fluctuation term, the variation of the radiative functional is proportional to \(\delta S/\delta g\); the notes conclude independence on the classical shell.",
     r"BRST variation yields a gauge-parameter identity of the form \(\delta\Gamma=\Gamma_{,i}K^i\) for the properly defined effective action. Consequently its value at a quantum stationary point is gauge independent. At one loop \(\Gamma=S+\hbar\Gamma_1+\cdots\), the corresponding variation of \(\Gamma_1\) vanishes on the classical shell \(S_{,i}=0\).",
     r"\citet[pp.~173--188]{nielsen1975gauge} is the 1975 original publication lead, checked indirectly. The explicitly read primary later treatment \citet[\S2.1, eq.~(1)]{espinosa2015higgstory} states the effective-action identity and its quantum-stationary consequence. The one-loop classical-shell consequence follows by expanding that identity consistently in \(\hbar\). Neither source permits classical and quantum equations of motion to be identified at all orders.",
     ["nielsen1975gauge","espinosa2015higgstory"],reconstruction=r"The effective-action interpretation, loop expansion and distinction between the classical and quantum shell are supplied. The displayed notebook formula is treated as a schematic first-order identity; the later Higgs-background treatment checks the principle, not every gravity-specific detail.",match="partial",verification="read the result",status=r"on-shell gauge independence is established within the BRST perturbative hypotheses; off-shell effective actions generally depend on gauge.",confidence="medium")
item(472,"P000869","method","Changing a gauge-fixing functional by a change of variables",
     r"The proof varies a quadratic gauge form \(F\) and compensates by \(h\mapsto h+\delta h\). An expectation of \(\delta h\) is written without its insertion, and equation (20) has an unmatched factor \(1/2\).",
     r"In a finite-dimensional regular gauge model, an admissible local gauge slice has an invertible derivative along gauge orbits. A change of slice can then be compensated locally, with its Jacobian included. In a formal field integral, the same manipulation requires a regulated measure, appropriate boundaries and consistent normalization. Invertibility of a quadratic fluctuation form alone does not prove global gauge independence.",
     r"\citet[\S8]{fuster2005brst} states the BRST gauge-independence argument in a modern form; \citet[\S\S2--3]{faddeevpopov1974gravity} gives its earlier determinant setting. Neither validates the two literal misprints.",
     ["fuster2005brst","faddeevpopov1974gravity"],reconstruction=r"The elementary change-of-variables conditions replace the notebook's unrestricted functional-integral claim. The flawed equality is not used as a proof.",literal="false as written",match="partial",status=r"the local/formal argument is standard; a nonperturbative global statement is not established by these formulas.")
item(472,"P000869-P000870","definition","Maxwell gauge invariance and its Hessian kernel",
     r"\(S[A]=-\frac14\int(\partial_\mu A_\nu-\partial_\nu A_\mu)^2\) is invariant under \(A_\mu\mapsto A_\mu+\partial_\mu\xi\); the Hessian is degenerate.",
     r"For a flat background and suitable compact support or boundary conditions, \(F=dA\) is unchanged by \(A\mapsto A+d\xi\). The quadratic operator \(K_{\mu\nu}=\eta_{\mu\nu}\Box-\partial_\mu\partial_\nu\) satisfies \(K_{\mu\nu}\partial^\nu\xi=0\), so no inverse exists before removing gauge directions.",
     r"This is the Abelian special case of the earlier gauge-action construction; compare \citet[eqs.~(1)--(6)]{yangmills1954conservation}.",
     ["yangmills1954conservation"],literal="correct",status=r"the algebraic kernel identity is elementary and unchanged; boundary conditions determine residual modes.")
item(472,"P000870","construction","Lorenz and generalized linear gauges for electromagnetism",
     r"The two examples add \((\partial\cdot A)^2/(2\alpha)\) and \((\partial\cdot A+\beta n\cdot A)^2/(2\alpha)\).",
     r"A linear gauge functional \(F(A)=L^\mu A_\mu\) produces a quadratic gauge-fixing term. For Abelian transformations its Faddeev--Popov operator is \(L^\mu\partial_\mu\), independent of \(A\), and the ghosts decouple when that operator and its boundary prescription are fixed. Gauge parameters must avoid singular gauges or require a separate limiting prescription.",
     r"\citet[\S\S1--3]{faddeevpopov1974gravity} reviews the determinant construction for which Maxwell theory is the linear case.",
     ["faddeevpopov1974gravity"],reconstruction=r"The fixed vector \(n\), residual gauge kernel and parameter restrictions are specified; the notes do not prove equivalence for every \(\alpha,\beta\).",match="partial",status=r"the two expressions are standard admissible local gauge choices when the corresponding operator can be inverted.")
save()

talk(473,"1979-10-29","I. A. Batalin","P000871-P000877","Faddeev--Popov reduction and BRST invariance",
     r"The scan on P000871 dates this lecture \ru{29/X-79}, so 29 October is used here; the supplied catalogue's 29 September is recorded as a provenance discrepancy. After stationary phase and Maxwell gauge degeneracy, a finite-dimensional group-action model derives the gauge-slice determinant and ghost representation. BRST transformations, physical unitarity, gauge independence, open supergravity algebras and the Yang--Mills example follow. The notes are an exposition of methods circulating before the talk, not an instance of the later odd-antibracket BV formalism.")
item(473,"P000871","construction","Sources and time-ordered correlation functions",
     r"The notes define \(Z(J)=c\int e^{iW[\varphi]+iJ\varphi}\,d\mu(\varphi)\) and identify source derivatives with products of fields.",
     r"With \(\hbar=1\) and normalization \(Z(0)=1\), the formal time-ordered \(n\)-point function is \(i^{-n}\delta^n Z/\delta J(x_1)\cdots\delta J(x_n)|_{J=0}\). For non-normalized \(Z\), divide by \(Z(0)\). Derivatives of \(-i\log Z\) generate connected functions with the corresponding powers of \(i\).",
     r"The construction is reviewed before the seminar in \citet[\S1]{faddeevpopov1974gravity}, Russian 1973/English 1974.",
     ["faddeevpopov1974gravity"],reconstruction=r"The missing factors, evaluation at zero source and normalization are stated explicitly. No measure-existence assertion is added.",literal="correct with missing hypotheses",status=r"this is a formal or suitably constructed generating-functional identity, not a proof of existence of an interacting quantum field theory.")
item(473,"P000871","method","Coupling expansion versus expansion around a classical solution",
     r"A scalar \(\varphi^4\) example precedes two schemes: a coupling expansion and stationary phase near a solution. The notebook says the first is inapplicable to gravity and writes a dot on \(\varphi\) in the mass term.",
     r"For a scalar field the conventional action has a kinetic term, a mass term \(m^2\varphi^2/2\), and a quartic interaction. Coupling expansion and an \(\hbar\)-expansion about a saddle are distinct formal organizations; both can be used in perturbative gravity after gauge fixing. Nonrenormalizability by power counting does not make every coupling expansion undefined.",
     r"\citet[\S\S1--2]{faddeevpopov1974gravity} explicitly presents perturbation theory for gravity before 1979 and therefore rules out the blanket prohibition.",
     ["faddeevpopov1974gravity"],reconstruction=r"The mass-term emendation and the distinction between perturbative definability and renormalizability are editorial.",literal="false as written",match="partial",status=r"the two expansions are standard; the printed mass term and absolute prohibition need correction.")
item(473,"P000871-P000872","theorem","Nondegenerate stationary phase and its missing normalization",
     r"The notes approximate an oscillatory integral by the inverse square root of the Hessian determinant and a value at a stationary point.",
     r"For real \(S\in C^\infty\), \(a\in C_c^\infty(\mathbb R^n)\), and a unique nondegenerate critical point \(x_0\) in the relevant support, as \(\hbar\downarrow0\), \(\int e^{iS(x)/\hbar}a(x)\,dx=e^{iS(x_0)/\hbar}(2\pi\hbar)^{n/2}e^{i\pi\operatorname{sgn}S''(x_0)/4}|\det S''(x_0)|^{-1/2}[a(x_0)+O(\hbar)]\). Multiple critical points contribute a sum; a critical manifold requires a different theorem.",
     r"The finite-dimensional Gaussian basis of the earlier path-integral method is given in \citet[\S1]{faddeevpopov1974gravity}. The precise stationary-phase statement here is a classical mathematical reconstruction, not a new result identified with this lecture.",
     ["faddeevpopov1974gravity"],reconstruction=r"Amplitude, support, nondegeneracy, absolute determinant, signature phase and power of \(2\pi\hbar\) are supplied. The generic remainder is \(O(\hbar)\), not the notebook's stronger small-o assertion.",literal="false as written",match="partial",status=r"the finite-dimensional theorem is settled; it does not justify an infinite-dimensional gravity saddle expansion without further work.")
item(473,"P000872","claim","Gauge degeneracy obstructs the naive saddle formula",
     r"For Maxwell theory the Hessian annihilates gradients, and integration along a gauge orbit is described as producing a group-volume factor.",
     r"If \(S\) is invariant under a smooth group action, its Hessian at a critical point annihilates infinitesimal orbit directions. Thus the isolated nondegenerate stationary-phase formula cannot be applied in those directions. For Maxwell theory the identity is \((\eta_{\mu\nu}\Box-\partial_\mu\partial_\nu)\partial^\nu\xi=0\).",
     r"This is the obstruction addressed by the earlier Faddeev--Popov construction; \citet[\S2]{faddeevpopov1974gravity}.",
     ["faddeevpopov1974gravity"],status=r"the degeneracy statement is exact; an infinite group volume is a formal description unless a quotient measure is defined.")
item(473,"P000872-P000873","construction","Infinitesimal group generators, Lie equations and invariant measures",
     r"A transformation \(g\mapsto f(g,\theta)\), generators \(R_\alpha^a\), structure constants and a matrix \(\lambda(\theta)\) are introduced. Divergence-free generators are associated with a \ru{унимодулярная} group.",
     r"For a smooth Lie-group action, the derivatives of \(f\) along group coordinates factor through fundamental vector fields and a Maurer--Cartan frame. A density \(\rho\,dg\) is invariant precisely when \(\partial_a(\rho R_\alpha^a)=0\). This is an action-and-density condition. Unimodularity of the abstract group means its left and right Haar measures agree and is not equivalent to \(\partial_aR_\alpha^a=0\) in arbitrary coordinates on the acted-on manifold.",
     r"The invariant-measure requirement is part of the pre-existing gauge argument; compare \citet[\S2]{faddeevpopov1974gravity}. \citet[\S~II]{bering1997geometry} later makes its geometric measure assumptions explicit (1997 preprint, revised 1998).",
     ["faddeevpopov1974gravity","bering1997geometry"],reconstruction=r"The density and the distinction between group unimodularity and volume preservation of a particular action are supplied.",literal="false as written",match="partial",status=r"the Lie-action identities are standard; the notebook's terminology should not be used as an equivalence theorem.")
item(473,"P000873","definition","An admissible local gauge slice",
     r"The condition \(\psi^\alpha(f(g,\theta))=0\) is required to have one solution \(\theta\) for every \(g\); the notes call this a section.",
     r"For a locally free action of an \(m\)-dimensional Lie group, \(m\) gauge functions define a local slice when \(M^\alpha{}_\beta(g)=d\psi^\alpha_g(R_\beta(g))\) is invertible on the slice. The inverse-function theorem then gives local uniqueness near a chosen intersection. Global existence and uniqueness require additional assumptions and generally fail in non-Abelian gauge theory.",
     r"The local determinant method predates 1979. The global obstruction is the topic of \citet[pp.~1--19]{gribov1978quantization}, published in 1978, but that original text was not recovered in this audit. The independently read later primary analysis \citet[\S~II]{bering1997geometry} explicitly excludes global Gribov problems from its gauge-independence argument.",
     ["gribov1978quantization","bering1997geometry"],reconstruction=r"Local uniqueness is substituted for the universal global section that the notes assume rather than prove.",match="partial",verification="indirect",status=r"local slices remain useful; a universal global slice is not available in general.",confidence="medium")
item(473,"P000873","theorem","Faddeev--Popov determinant identity",
     r"Equations (21)--(27) derive \(1=\int\delta(\psi(f(g,\theta)))\Delta_\psi(f(g,\theta))\,d\sigma(\theta)\), with \(\Delta_\psi=\det(\psi_{,a}R^a)\). Equation (23) omits \(f\) in one argument.",
     r"If the orbit-to-gauge map has exactly one regular zero in the integration chart, the ordinary real delta-function change-of-variables formula gives \(1=\int \delta^m(\psi(f(g,\theta)))|\det \partial_\theta\psi(f(g,\theta))|\,d^m\theta\). With a consistently oriented formal measure one uses the signed determinant. The group-coordinate Jacobian converts this to the Haar-measure form.",
     r"\citet[\S2]{faddeevpopov1974gravity} gives the earlier determinant insertion. The local real-variable identity explains exactly which regularity and multiplicity conditions are needed.",
     ["faddeevpopov1974gravity"],reconstruction=r"The absolute value for positive measures, possible orientation convention and unique-zero hypothesis are supplied. Equation (23)'s argument must be \(f(g,\theta)\).",literal="correct with missing hypotheses",status=r"the local change-of-variables identity is settled; multiple gauge intersections change the naive formula.")
item(473,"P000873-P000874","method","Factoring gauge volume from an invariant integral",
     r"The invariant integrand and measure are changed by \(g\mapsto f(g,\theta)\), producing a common gauge-volume factor and a reduced delta-function integral.",
     r"For a free proper action with compatible measures and convergent integrals, disintegration along orbits yields a quotient integral and the orbit-volume factor. In the formal field-theoretic version, common infinite gauge volumes are canceled only after a specified normalization; insertion of the determinant and compatible gauge slice is essential.",
     r"The preceding reduction is the pre-1979 Faddeev--Popov method; \citet[\S2]{faddeevpopov1974gravity}.",
     ["faddeevpopov1974gravity"],reconstruction=r"The honest finite-dimensional hypotheses are supplied. The notes' repeated \(d\sigma\) in an integral over field coordinates is a variable-label error, not a new measure.",match="partial",status=r"the geometric quotient construction is standard where its hypotheses hold; cancellation of divergent factors alone is not a proof.")
item(473,"P000874-P000875","construction","Gauge averaging and the indispensable normalization",
     r"The slice is moved to \(\psi(g)=c\), averaged with \(e^{i\Omega(c)}dc\), and equation (40) divides by \(\int e^{i\Omega(c)}dc\). The next displayed equality drops this denominator.",
     r"If \(I(c)\) is independent of the admissible slice value \(c\), then \(\int w(c)I(c)\,dc/\int w(c)\,dc=I\), provided the denominator is nonzero and integrals or their regularized meanings exist. Taking \(w=e^{i\Omega}\) gives a gauge-fixing action but not an unnormalized gauge-independent partition function.",
     r"This is the normalization step in the earlier covariant gauge procedure; \citet[\S3]{faddeevpopov1974gravity}.",
     ["faddeevpopov1974gravity"],reconstruction=r"The distinction between the normalized quotient and the raw averaged integral is explicit.",literal="false as written",match="partial",status=r"the normalized identity is elementary; equation (41) needs the factor already present in equation (40).")
item(473,"P000874-P000875","construction","Grassmann representation of the gauge determinant",
     r"The determinant \(\det(\psi_{,a}R^a)\) is represented using anticommuting \(\xi,\bar\xi\), producing \(W_{\rm eff}=W+\Omega(\psi)+\bar\xi\,\psi_{,a}R^a\xi\).",
     r"For an \(m\times m\) matrix \(M\), a fixed Berezin integration order gives \(\int d\bar c\,dc\,e^{-\bar cMc}=\det M\). In an oscillatory convention \(e^{i\bar cMc}\), the harmless factor \(i^m\) is absorbed in normalization. Ghost parity is opposite to the gauge-parameter parity; fermionic gauge directions require commuting ghosts.",
     r"\citet[\S3, following eq.~(3.21)]{faddeevpopov1974gravity} uses the determinant representation. The graded first/second-class extension is the pre-1979 lead \citet[pp.~343--348]{fradkinfradkina1978quantization}.",
     ["faddeevpopov1974gravity","fradkinfradkina1978quantization"],reconstruction=r"Finite-dimensional normalization and the graded qualification are supplied; the general fermionic extension is not claimed to have been read in the inaccessible 1978 article.",match="exact",status=r"the finite-dimensional Berezin identity is exact; its functional-integral use remains subject to the chosen regularization.")
item(473,"P000875-P000876","construction","BRST transformations and the antighost qualification",
     r"Equations (43)--(46) give \(\delta g^a=R_\alpha^a\xi^\alpha\mu\), \(\delta\xi^\alpha=\frac12t^\alpha_{\beta\gamma}\xi^\beta\xi^\gamma\mu\), and \(\delta\bar\xi_\alpha=\Omega_{,\alpha}(\psi)\mu\), with odd constant \(\mu\).",
     r"For a closed Lie gauge algebra, \(s\phi=R_\alpha c^\alpha\), \(sc^\alpha=-\frac12f^\alpha_{\beta\gamma}c^\beta c^\gamma\) define a nilpotent odd derivation with consistent left/right conventions. Add an auxiliary field \(b_\alpha\) and set \(s\bar c_\alpha=b_\alpha,\ sb_\alpha=0\) for off-shell nilpotence. Eliminating \(b\) by its equation yields the notebook's gauge-function variation, whose antighost nilpotence is generally only on shell.",
     r"The original development was publicly announced in 1974 and appears in the April 1975 report \citet[\S\S2--3]{becchirouetstora1975renormalization}; \citet[\S6, eqs.~(6.1)--(6.5)]{fuster2005brst} makes the auxiliary-field formulation explicit.",
     ["becchirouetstora1975renormalization","fuster2005brst"],reconstruction=r"Signs are translated from the notebook's right odd parameter. The auxiliary field is a modern clarification, not a field visibly introduced in this passage.",match="partial",status=r"the BRST construction is established; nilpotence of the displayed antighost rule requires the stated on-shell qualification.")
item(473,"P000876","claim","Chevalley--Eilenberg cancellation behind BRST nilpotence",
     r"The notes introduce \(\Gamma_\alpha=R_\alpha^a\partial_a\), compute \((\Gamma_\alpha\xi^\alpha)^2\), and cancel it using the ghost transformation.",
     r"If \([\Gamma_\alpha,\Gamma_\beta]=f_{\alpha\beta}^\gamma\Gamma_\gamma\), then \(s=c^\alpha\Gamma_\alpha-\frac12f_{\alpha\beta}^{\gamma}c^\alpha c^\beta\partial/\partial c^\gamma\) satisfies \(s^2=0\). The representation identity and Jacobi identity give the cancellations; this statement applies to a closed Lie algebra action, not automatically to field-dependent or on-shell closing algebras.",
     r"The pre-1979 BRST report \citet[\S2]{becchirouetstora1975renormalization} presents this algebraic mechanism; \citet[\S4]{fuster2005brst} relates it to cohomology.",
     ["becchirouetstora1975renormalization","fuster2005brst"],reconstruction=r"The operator is written with a single left-derivative convention. Structure functions require the corresponding more general resolution.",literal="correct with missing hypotheses",status=r"the nilpotence identity is exact under the closed-algebra assumptions.")
item(473,"P000876","claim","Physical unitarity and cancellation of ghost states",
     r"The notes discuss a unitary \(S\)-operator, internal ghosts, and cancellations leaving physical particles.",
     r"In an anomaly-free perturbative BRST theory, the conserved nilpotent charge defines physical states through its cohomology. If the induced inner product is positive and unphysical states form canceling sectors, the \(S\)-operator induced on physical cohomology is unitary. The enlarged ghost state space itself need not have a positive-definite inner product.",
     r"\citet[\S3, pp.~29--39 and abstract]{becchirouetstora1975renormalization} proves physical unitarity and gauge-parameter independence for its specified massive Higgs-model setting, not for every conceivable gauge theory.",
     ["becchirouetstora1975renormalization"],reconstruction=r"The physical quotient and positivity assumptions prevent the bare symbolic equality from being interpreted as a universal Hilbert-space theorem.",match="partial",status=r"physical perturbative unitarity is established for standard anomaly-free models; the notes do not settle global or nonperturbative unitarity of supergravity.")
item(473,"P000876-P000877","method","Field-dependent BRST parameters and gauge independence",
     r"A field-dependent odd parameter involving \(\bar\xi\,\delta\psi\) is used to cancel a change of gauge; Slavnov identities are mentioned.",
     r"An infinitesimal change of gauge fermion changes the BRST-exact gauge-fixing action. A BRST change of integration variables, with its super-Jacobian included, leaves expectation values of BRST-closed observables unchanged when the measure is BRST invariant, boundary terms vanish, and the integration domain is admissible. A field-dependent parameter generally has a nontrivial Jacobian even if a constant BRST transformation preserves the measure.",
     r"The earlier BRST report \citet[\S3, pp.~29--34]{becchirouetstora1975renormalization} provides the gauge-independence identities; \citet[\S V, eqs.~(V.8)--(V.9)]{bering1997geometry} explicitly treats the later geometric gauge-fixing argument and its endpoint condition.",
     ["becchirouetstora1975renormalization","bering1997geometry"],reconstruction=r"The measure/domain qualifications and the distinction between constant and field-dependent parameters are made explicit.",status=r"the formal gauge-independence theorem is standard with these hypotheses; it is not a proof that gauge copies or anomalies cannot occur.")
item(473,"P000877","remark","Open supergravity algebras",
     r"The lecture says supergravity is \ru{не группа}, in contrast with the preceding Yang--Mills derivation.",
     r"The identifiable mathematical content is that commutators of gauge transformations in some supergravity formulations close only modulo equations of motion, or have field-dependent coefficients. This is an open gauge algebra. It is not the assertion that no groupoid, integrated symmetry or auxiliary-field formulation can exist.",
     r"\citet[pp.~141--152]{kallosh1978modified} is a pre-talk lead; \citet[\S2.2]{fuster2005brst} verifies the later precise distinction. The original 1978 full text was not accessed.",
     ["kallosh1978modified","fuster2005brst"],reconstruction=r"Open-algebra terminology is supplied. The notes do not specify which supergravity or auxiliary fields are intended.",cls="E",match="partial",verification="indirect",literal="not determinable",status=r"the distinction is established, but no model-specific closure identity can be recovered from this sentence.",confidence="medium")
item(473,"P000877","construction","Yang--Mills curvature, infinitesimal gauge generator and ghosts",
     r"The final example takes a compact semisimple group, \(F=dA+[A,A]\), a Lorenz gauge, and a ghost term \(-(\partial_\mu\bar\xi)D^\mu\xi\). Equation (60) abbreviates the functional generator.",
     r"For a connection \(A\) on a fixed bundle and invariant inner product on its compact semisimple Lie algebra, \(F_A=dA+\frac12[A,A]\) and \(\delta_\epsilon A=D_A\epsilon\). In a local Lorenz gauge the Faddeev--Popov operator is \(\partial^\mu D_\mu\), with ghost action represented after integration by parts. As a distributional kernel, \(R_{\mu\,b}^{a}(x,y)=D_{\mu\,b}^{a}(x)\delta(x-y)\); the delta function and spacetime index cannot be dropped in a literal kernel equation.",
     r"\citet[eqs.~(1)--(11)]{yangmills1954conservation} supplies the classical 1954 model; \citet[\S2]{becchirouetstora1975renormalization} gives its pre-1979 ghost and BRST extension.",
     ["yangmills1954conservation","becchirouetstora1975renormalization"],reconstruction=r"Bundle, contraction, boundary and kernel conventions are supplied; the gauge parameter's reciprocal can be absorbed by renaming it.",literal="correct with missing hypotheses",status=r"the classical and perturbative construction is standard; a rigorous four-dimensional continuum quantum theory is a separate problem.")
